CREATE PROCEDURE usp_CustomersByCountry
    @Country NVARCHAR(15)
AS
SELECT CustomerID, CompanyName, City
FROM Customers
WHERE Country = @Country;
GO
EXEC usp_CustomersByCountry 'Germany';

CREATE PROCEDURE usp_ProductsInPriceRange
    @Min MONEY,
    @Max MONEY
AS
SELECT ProductName, UnitPrice
FROM Products
WHERE UnitPrice BETWEEN @Min AND @Max
ORDER BY UnitPrice;
GO
EXEC usp_ProductsInPriceRange @Min = 20, @Max = 30;

ALTER PROCEDURE usp_CustomersByCountry
    @Country NVARCHAR(15) = 'USA'
AS
SELECT CustomerID, CompanyName, City
FROM Customers
WHERE Country = @Country;
GO
EXEC usp_CustomersByCountry;          -- USA
EXEC usp_CustomersByCountry 'France';

CREATE PROCEDURE usp_CountProducts
    @CategoryID INT,
    @Count INT OUTPUT
AS
SELECT @Count = COUNT(*)
FROM Products
WHERE CategoryID = @CategoryID;
GO
DECLARE @n INT;
EXEC usp_CountProducts 1, @n OUTPUT;
SELECT @n AS ProductsInCategory;

CREATE PROCEDURE usp_CustomerExists
    @CustomerID NCHAR(5)
AS
IF EXISTS (SELECT 1 FROM Customers WHERE CustomerID = @CustomerID)
    RETURN 1;
RETURN 0;
GO
DECLARE @r INT;
EXEC @r = usp_CustomerExists 'ALFKI';
SELECT @r AS ALFKI;
EXEC @r = usp_CustomerExists 'ZZZZZ';
SELECT @r AS ZZZZZ;

CREATE PROCEDURE usp_AddShipper
    @Name  NVARCHAR(40),
    @Phone NVARCHAR(24)
AS
INSERT INTO Shippers (CompanyName, Phone) VALUES (@Name, @Phone);
SELECT SCOPE_IDENTITY() AS NewShipperID;
GO
BEGIN TRANSACTION;
EXEC usp_AddShipper 'Fast Lane', '(03) 555-1234';
ROLLBACK;

CREATE PROCEDURE usp_RaisePrice
    @ProductID INT,
    @Percent   DECIMAL(5,2)
AS
IF @Percent > 50
BEGIN
    PRINT N'אחוז גבוה מדי';
    RETURN;
END
UPDATE Products
SET UnitPrice = UnitPrice * (1 + @Percent / 100)
WHERE ProductID = @ProductID;
GO
BEGIN TRANSACTION;
EXEC usp_RaisePrice 1, 10;
EXEC usp_RaisePrice 1, 80;   -- רק הודעה
SELECT ProductName, UnitPrice FROM Products WHERE ProductID = 1;
ROLLBACK;

